CREATE TABLE signup_enrollments(token_hash TEXT PRIMARY KEY REFERENCES enrollment_tokens(token_hash),project_name TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE timestamp_leases(sha256 TEXT PRIMARY KEY,lease_until TEXT NOT NULL,owner TEXT NOT NULL);
CREATE TRIGGER proof_created_audit AFTER INSERT ON proofs BEGIN INSERT INTO audit_events(project_id,actor_user_id,event_type,target_type,target_id,created_at) SELECT a.project_id,v.created_by,'PROOF_CREATED','proof',NEW.id,NEW.created_at FROM asset_versions v JOIN assets a ON a.id=v.asset_id WHERE v.id=NEW.asset_version_id; END;
CREATE TRIGGER proof_confirmed_guard BEFORE UPDATE OF ots_proof,proof_status,timestamp_status,bitcoin_status,timestamp_created_at,bitcoin_confirmed_at,bitcoin_block,timestamp ON proofs WHEN OLD.proof_status='CONFIRMED' BEGIN SELECT RAISE(ABORT,'confirmed proof is immutable'); END;
CREATE TRIGGER invite_consume_guard BEFORE UPDATE OF consumed_at ON project_invites WHEN OLD.consumed_at IS NOT NULL OR NEW.consumed_at IS NULL BEGIN SELECT RAISE(ABORT,'invitation already consumed'); END;
CREATE TRIGGER delivery_created_history AFTER INSERT ON deliveries BEGIN INSERT INTO delivery_history(delivery_id,status,actor_user_id,comment,created_at) VALUES(NEW.id,NEW.receipt_status,NEW.delivered_by,NEW.comment,NEW.delivered_at); INSERT INTO audit_events(project_id,actor_user_id,event_type,target_type,target_id,created_at) SELECT a.project_id,NEW.delivered_by,'DELIVERY_CREATED','delivery',NEW.id,NEW.delivered_at FROM asset_versions v JOIN assets a ON a.id=v.asset_id WHERE v.id=NEW.asset_version_id; END;
CREATE TRIGGER delivery_receipt_history AFTER UPDATE ON deliveries BEGIN INSERT INTO delivery_history(delivery_id,status,actor_user_id,comment,created_at) VALUES(NEW.id,NEW.receipt_status,NEW.recipient_user_id,NEW.comment,COALESCE(NEW.received_at,strftime('%Y-%m-%dT%H:%M:%fZ','now'))); INSERT INTO audit_events(project_id,actor_user_id,event_type,target_type,target_id,created_at) SELECT a.project_id,NEW.recipient_user_id,'DELIVERY_'||NEW.receipt_status,'delivery',NEW.id,COALESCE(NEW.received_at,strftime('%Y-%m-%dT%H:%M:%fZ','now')) FROM asset_versions v JOIN assets a ON a.id=v.asset_id WHERE v.id=NEW.asset_version_id; END;
